def copy_links_to_bindings(apps, schema_editor):
    """Each old one-lab guild link becomes a server row plus one lab binding, and
    its two channel columns become that binding's routes."""
    Link = apps.get_model("integrations", "DiscordGuildLink")
    Binding = apps.get_model("integrations", "DiscordTargetBinding")
    Route = apps.get_model("integrations", "DiscordChannelRoute")
    for link in Link.objects.exclude(lab__isnull=True):
        state = {"active": "active", "pending_setup": "pending_setup"}.get(
            link.state, "active"  # a kicked guild keeps an active binding; the
        )  # guild's own KICKED state silences it until a re-install
        binding = Binding.objects.create(
            guild=link,
            lab_id=link.lab_id,
            state=state,
            activated_by_id=link.installed_by_id,
            activated_at=link.confirmed_at or (link.installed_at if state == "active" else None),
            addon_ok=link.addon_ok,
            channel_checked_at=link.channel_checked_at,
            last_error_code=link.last_error_code,
        )
        if link.announcement_channel_id:
            Route.objects.create(
                binding=binding,
                purpose="deadlines",
                channel_id=link.announcement_channel_id,
                verified_at=link.channel_verified_at,
                ok=link.announcement_channel_ok,
                checked_at=link.channel_checked_at,
            )
        if link.updates_channel_id:
            Route.objects.create(
                binding=binding,
                purpose="updates",
                channel_id=link.updates_channel_id,
                verified_at=link.updates_channel_verified_at,
                ok=link.updates_channel_ok,
                checked_at=link.channel_checked_at,
            )


def copy_bindings_to_links(apps, schema_editor):
    """Reverse: put each server's first lab binding back on the link. A server with
    several bindings keeps only the oldest, since the old model held one."""
    Link = apps.get_model("integrations", "DiscordGuildLink")
    Binding = apps.get_model("integrations", "DiscordTargetBinding")
    for link in Link.objects.all():
        binding = (
            Binding.objects.filter(guild=link, lab__isnull=False)
            .order_by("activated_at", "id")
            .first()
        )
        if binding is None:
            continue
        routes = {r.purpose: r for r in binding.routes.all()}
        link.lab_id = binding.lab_id
        link.addon_ok = binding.addon_ok
        if "deadlines" in routes:
            link.announcement_channel_id = routes["deadlines"].channel_id
            link.channel_verified_at = routes["deadlines"].verified_at
            link.announcement_channel_ok = routes["deadlines"].ok
        if "updates" in routes:
            link.updates_channel_id = routes["updates"].channel_id
            link.updates_channel_verified_at = routes["updates"].verified_at
            link.updates_channel_ok = routes["updates"].ok
        link.save()


